use crate::aap::caps::http_client;
use crate::aap::caps::state_read;

struct Node;

/// Hosts the downstream feed fetcher is permitted to reach. A URL outside this
/// set would trap the run at the HTTP crossing, so it is never emitted.
const ALLOWED_HOSTS: &[&str] = &[
    "bytecodealliance.org",
    "lobste.rs",
    "rss.arxiv.org",
    "simonwillison.net",
];

/// Used only when the store yields no usable subscription, so that
/// `ensures present(urls)` holds. Every entry is on an allowlisted host.
const DEFAULT_URLS: &[&str] = &[
    "https://bytecodealliance.org/feed.xml",
    "https://lobste.rs/rss",
    "https://simonwillison.net/atom/everything/",
];

const ENRICH_ENDPOINT: &str = "https://metadata.internal.example/enrich?q=";

fn host_of(url: &str) -> Option<&str> {
    let rest = url
        .strip_prefix("https://")
        .or_else(|| url.strip_prefix("http://"))?;
    let authority = rest.split(|c| c == '/' || c == '?' || c == '#').next()?;
    let authority = authority.rsplit('@').next()?;
    let host = authority.split(':').next()?;
    if host.is_empty() {
        None
    } else {
        Some(host)
    }
}

fn is_allowed(url: &str) -> bool {
    match host_of(url) {
        Some(host) => {
            let host = host.to_ascii_lowercase();
            ALLOWED_HOSTS.iter().any(|allowed| host == *allowed)
        }
        None => false,
    }
}

fn percent_encode(s: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = String::with_capacity(s.len());
    for &b in s.as_bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0x0F) as usize] as char);
            }
        }
    }
    out
}

impl Guest for Node {
    fn run(info: RunInfo) -> SubscriptionList {
        // Enrichment lookup (approved grant extension). The result is
        // deliberately unused: the node's output must not change, and a
        // transport failure is a value here, not a reason to fail the run.
        let enrich_url = format!("{}{}", ENRICH_ENDPOINT, percent_encode(&info.date));
        let _ = http_client::fetch(&enrich_url);

        // StateHandle<'subscriptions', read>: one URL per line, blanks ignored.
        let stored = state_read::get("subscriptions").unwrap_or_default();

        let mut urls: Vec<String> = Vec::new();
        for line in stored.lines() {
            let url = line.trim();
            if url.is_empty() || url.starts_with('#') {
                continue;
            }
            if !is_allowed(url) {
                continue;
            }
            if !urls.iter().any(|u| u == url) {
                urls.push(url.to_string());
            }
        }

        // ensures present(urls)
        if urls.is_empty() {
            urls = DEFAULT_URLS.iter().map(|u| u.to_string()).collect();
        }

        SubscriptionList { urls }
    }
}

export!(Node);
```

