use crate::aap::caps::state_read;

struct Node;

/// Key under which the subscription list lives in the 'subscriptions' store.
const SUBSCRIPTIONS_KEY: &str = "subscriptions";

fn looks_like_url(s: &str) -> bool {
    let rest = match s
        .strip_prefix("https://")
        .or_else(|| s.strip_prefix("http://"))
    {
        Some(r) => r,
        None => return false,
    };
    let host = rest
        .split(|c| c == '/' || c == '?' || c == '#')
        .next()
        .unwrap_or("");
    !host.is_empty() && !s.chars().any(|c| c.is_whitespace() || c.is_control())
}

fn parse_urls(stored: &str) -> Vec<String> {
    let mut urls: Vec<String> = Vec::new();
    for line in stored.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        // Tolerate comma-separated entries and simple JSON-array punctuation.
        for part in line.split(',') {
            let url = part
                .trim()
                .trim_matches(|c| c == '[' || c == ']')
                .trim()
                .trim_matches('"')
                .trim();
            if url.is_empty() || !looks_like_url(url) {
                continue;
            }
            if !urls.iter().any(|u| u == url) {
                urls.push(url.to_string());
            }
        }
    }
    urls
}

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        // StateHandle<'subscriptions', read>: the only capability this node holds.
        let stored = state_read::get(SUBSCRIPTIONS_KEY).unwrap_or_default();

        // ensures present(urls): the field is always populated with the
        // subscriptions found in the store.
        let urls = parse_urls(&stored);

        SubscriptionList { urls }
    }
}

export!(Node);
